import{prepareReportLeave,persistReportLeave,assertReportLeaveCurrent}from'./time-leave-source.mjs';
// Typed native time service. The caller owns one transaction and connection.
import{lockLeaveRosterPeople}from'./leave-roster-source.mjs';
import {createHash} from 'node:crypto';
import {q,one,id,text,list,obj,same,bad,deny,conflict,missing,revision,hash,command,audit,emit,authorization,requireAccess,currentOperator,paging,search} from './platform-core.mjs';
import {sameHuman,humanIsPerson} from './human-identity.mjs';
import {accessFor,companyDescendants,ledgerDescendants} from './foundation.mjs';
import {readNamedWorkbook,columnName} from './customer-performance-import.mjs';
