export const ACTIONS=['plan.create','plan.publish','day.set','segment.save','segment.move','segment.copy','segment.delete','shift.save','change.submit','change.agree','change.decide','punch.submit','punch.correction','punch.correction.decide','report.create','report.adjust','report.confirm','import.preview','import.commit'];
async function mutationContext(t,userId,name,input){let entity;if(name.startsWith('segment.')||name.startsWith('day.')||name==='change.submit')entity=await one(t,'SELECT*FROM ty_time_plan_version WHERE id=$1',[id(input.plan_id)]);else if(name==='plan.publish')entity=await one(t,'SELECT*FROM ty_time_plan_version WHERE id=$1',[id(input.id)]);else if(name.startsWith('report.')&&!name.endsWith('.create'))entity=await one(t,'SELECT*FROM ty_time_report_version WHERE id=$1',[id(input.id)]);else if(name==='import.commit')entity=await one(t,'SELECT*FROM ty_time_import_batch WHERE id=$1',[id(input.id)]);else if(name==='change.decide'||name==='change.agree')entity=await one(t,'SELECT c.*,p.period FROM ty_time_change_request c JOIN ty_time_plan_version p ON p.id=c.plan_id WHERE c.id=$1',[id(input.id)]);else if(name==='punch.correction.decide')entity=await one(t,'SELECT*FROM ty_time_punch_correction_request WHERE id=$1',[id(input.id)]);else if(name==='punch.submit'){const e=await one(t,'SELECT*FROM ty_employment WHERE id=$1',[id(input.employment_id)]);if(!e)missing();entity={...e,period:localDay(new Date()).slice(0,7)+'-01'};}else if(name==='punch.correction'){const ref=String(input.segment_id);entity=ref.startsWith('base:')?await one(t,'SELECT d.*,p.group_id,p.period FROM ty_roster_segment s JOIN ty_roster_day d ON d.id=s.day_id JOIN ty_roster_period p ON p.id=d.period_id WHERE s.id=$1',[id(ref.slice(5))]):await one(t,'SELECT s.*,p.group_id,p.period FROM ty_time_plan_segment s JOIN ty_time_plan_version p ON p.id=s.plan_id WHERE s.id=$1',[id(ref.replace(/^plan:/,''))]);}
 if(!entity&&!['plan.create','report.create','shift.save','import.preview'].includes(name))missing();if(entity&&input.group_id&&!same(entity.group_id,input.group_id))deny();const ctx=await context(t,userId,{...input,group_id:entity?.group_id||input.group_id,period:entity?.period?date(entity.period).slice(0,7):input.period});return{ctx,entity};}
async function safeResult(ctx,result){const out={...result};for(const key of['plan','report_version'])if(out[key]){const row=out[key],visible=await project(ctx,row);out[key]=visible||{id:row.id,status:row.status,revision:row.revision};}if(out.segment)out.segment=await project(ctx,{...out.segment,company_id:out.segment.work_company_id})||{id:out.segment.id,revision:out.segment.revision};if(out.segments){const rows=[];for(const row of out.segments){const visible=await project(ctx,{...row,company_id:row.work_company_id});if(visible)rows.push(visible);}out.segments=rows;}return out;}
// Counterparty acknowledgement is always a personal action, even for a store
// manager or bound HR account who also has broader business capabilities.
async function counterpartyContext(ctx,request){if(!request||!ctx.operator.person_id||!same(ctx.operator.group_id,ctx.group))deny('须由真实绑定的对方本人确认');const consent=await one(ctx.t,'SELECT person_id FROM ty_time_change_consent WHERE request_id=$1 AND person_id=$2',[request.id,ctx.operator.person_id]);if(!consent||!await humanIsPerson(ctx.t,ctx.userId,ctx.group,consent.person_id))deny('当前账号不是此换班待确认的真实对方');const matches=request.patches.filter(patch=>same(patch.person_id,consent.person_id));if(!matches.length)deny('待确认人员缺少真实目标工作关系');const personal={...ctx,self:true,resource:SELF};for(const patch of matches){const e=await employment(personal,patch.employment_id,day(patch.work_date));if(!same(e.person_id,consent.person_id))deny('确认工作关系不属于本人');await requireRow(personal,{employment_id:e.id,person_id:e.person_id,company_id:e.company_id},'submit');}return personal;}
export async function dispatchCommand(t,args){const{userId,operation,operationId,input={},[TIME_REVIEW_RECEIPT]:timeTicket}=args;const name=String(operation).replace(/^time\./,'');if(!ACTIONS.includes(name))bad('时间动作未登记');let{ctx,entity}=await mutationContext(t,userId,name,input);if(timeTicket!==undefined)ctx={...ctx,timeApproval:await authorizeNativeExecution(ctx,name,input,timeTicket)};if(name==='change.agree')ctx=await counterpartyContext(ctx,entity);if(ctx.self&&!['change.submit','change.agree','punch.submit','punch.correction'].includes(name))deny('本人入口不能维护或核准HR计划、报表与系统导入');const action=ctx.timeApproval?(ctx.timeApproval.outcome?'execute':'approve'):name.endsWith('.publish')||name.endsWith('.confirm')||name.endsWith('.decide')?'approve':name.endsWith('.create')||name.endsWith('.preview')?'create':name.endsWith('.submit')||name.endsWith('.correction')||name.endsWith('.agree')?'submit':name.endsWith('.delete')?'cancel':'update';let authRow={company_id:entity?.company_id||entity?.work_company_id||entity?.home_company_id||ctx.company,person_id:entity?.person_id||ctx.self&&ctx.operator.person_id,department_id:entity?.department_id};if(ctx.self&&['change.submit','change.agree','punch.submit','punch.correction'].includes(name))authRow={company_id:ctx.operator.company_id,person_id:ctx.operator.person_id};if(name==='change.submit'&&input.counterpart_segment_id){const own=await ownSwapReference(ctx,entity,input.own_segment_id,input.own_revision);ctx=own.personal;authRow={employment_id:own.source.employment_id,person_id:own.source.person_id,company_id:own.source.home_company_id};}await requireRow(ctx,authRow,action);return command(t,{userId,groupId:ctx.group,operation:'time.'+name,operationId,input,project:result=>safeResult(ctx,result),execute:async()=>{let result;if(name==='plan.create')result=await createPlan(ctx,input);else if(name==='plan.publish')result=await publishPlan(ctx,input);else if(name==='day.set')result=await setDay(ctx,input);else if(name==='segment.save')result=await saveSegment(ctx,input);else if(name==='segment.copy')result=await copyMove(ctx,input);else if(name==='segment.move')result=await copyMove(ctx,input,true);else if(name==='segment.delete')result=await deleteSegment(ctx,input);else if(name==='report.create')result=await createReport(ctx,input);else if(name==='report.adjust')result=await adjustReport(ctx,input);else if(name==='report.confirm')result=await confirmReport(ctx,input);else if(name==='import.preview')result=await previewImport(ctx,input);else if(name==='import.commit')result=await commitImport(ctx,input);else if(name==='shift.save')result=await saveShift(ctx,input);else if(name.startsWith('change.'))result=await changeCommand(ctx,name,input);else result=await punchCommand(ctx,name,input);await audit(t,userId,ctx.group,'time.'+name,'time_command',result.plan?.id||result.report_version?.id||result.change?.id||result.correction?.id||null,{operation_key:operationId});await emit(t,ctx.group,'time:'+name+':'+userId+':'+operationId,'time.command.completed',{operation:name,plan_id:result.plan?.id,report_id:result.report_version?.id});return result;}});}
async function saveShift(ctx,input){await metadata(ctx,{group_id:ctx.group},'update',['name','color','segments']);const code=text(input.code,'班次编码',1,40);if(!/^[A-Za-z0-9_-]+$/.test(code)||code==='TEMP')bad('班次编码只能用字母数字下划线，TEMP保留给临时班');const name=text(input.name,'班次名称',1,80),color=text(input.color,'班次颜色',7,7);if(!/^#[0-9A-Fa-f]{6}$/.test(color))bad('颜色格式无效');await ctx.t.query("SELECT pg_advisory_xact_lock(hashtextextended('time-shift:'||$1::text||':'||$2,0))",[ctx.group,code]);const latest=await one(ctx.t,'SELECT*FROM ty_time_shift_version WHERE group_id=$1 AND code=$2 ORDER BY version DESC LIMIT 1 FOR UPDATE',[ctx.group,code]);if(input.id){const old=await one(ctx.t,'SELECT*FROM ty_time_shift_version WHERE id=$1 AND group_id=$2',[id(input.id),ctx.group]);if(old){revision(old,input.expected_revision);if(old.code!==code||!same(old.id,latest?.id))conflict('班次已有新版本，请重新读取');}else{if(latest||!await one(ctx.t,'SELECT id FROM ty_shift_definition WHERE id=$1 AND group_id=$2 AND code=$3',[id(input.id),ctx.group,code]))conflict('来源班次已变化');}}else if(latest)conflict('班次编码已存在，请编辑其最新版本或另用新编码');
 const clock=v=>{if(typeof v!=='string'||!/^([01]\d|2[0-3]):[0-5]\d$/.test(v))bad('时间须为HH:mm');return Number(v.slice(0,2))*60+Number(v.slice(3));};const periods=list(input.segments||[{start_time:input.start_time,end_time:input.end_time,end_day_offset:input.end_day_offset||0,breaks:input.breaks||[]}]);if(!periods.length||periods.length>12)bad('班次须含1–12个明确工作区间');const ranges=[],segments=periods.map(value=>{const from=clock(value.start_time),offset=number(value.end_day_offset||0,'结束日期'),to=clock(value.end_time)+offset*1440;if(offset>1||to<=from)bad('结束日期须明确当天或次日且晚于开始');let last=from;const breaks=list(value.breaks||[]).map(rest=>{const start=clock(rest.start_time)+(rest.start_day_offset?1440:0),end=clock(rest.end_time)+(rest.end_day_offset?1440:0);if(start<from||end>to||end<=start||start<last)bad('模板休息须在工作区间内，跨午夜请明确次日');last=end;return{start_time:rest.start_time,end_time:rest.end_time,start_day_offset:rest.start_day_offset||0,end_day_offset:rest.end_day_offset||0,paid:false};});if(ranges.some(([start,end])=>start<to&&from<end))bad('一天多工作区间不得重叠');ranges.push([from,to]);return{start_time:value.start_time,end_time:value.end_time,end_day_offset:offset,breaks};});const shift=await one(ctx.t,'INSERT INTO ty_time_shift_version(group_id,code,name,color,version,segments,created_by)VALUES($1,$2,$3,$4,$5,$6::jsonb,$7)RETURNING*',[ctx.group,code,name,color,Number(latest?.version||0)+1,JSON.stringify(segments),ctx.userId]);return{shift};}
async function loadSourceSegment(ctx,ref){const key=segmentRef(ref);if(key.startsWith('base:')){const b=await baseline(ctx),s=b.segments.find(s=>s.id===key);if(!s)missing();return{...s,group_id:ctx.group,company_id:s.work_company_id,source_period_id:b.period.id};}const s=await one(ctx.t,'SELECT s.*,p.group_id,p.status plan_status FROM ty_time_plan_segment s JOIN ty_time_plan_version p ON p.id=s.plan_id WHERE s.id=$1 AND p.group_id=$2',[id(key.slice(5)),ctx.group]);if(!s)missing();return{...s,company_id:s.work_company_id,id:s.id,segment_ref:key};}

async function ownSwapReference(ctx,p,key,expected){if(!ctx.operator.person_id||!same(ctx.operator.group_id,ctx.group)||p.status!=='published')deny('本人互换须选择本人已发布计划');const source=await one(ctx.t,"SELECT*FROM ty_time_plan_segment WHERE id=$1 AND plan_id=$2 AND state='active'",[id(key),p.id]);if(!source||!await humanIsPerson(ctx.t,ctx.userId,ctx.group,source.person_id))deny('来源班段不是当前真实本人');if(expected!==undefined)revision(source,expected);if(source.leave_kind||source.overtime)bad('此入口只交换正常工作班段，不交换假期或独立加班');const e=await employment(ctx,source.employment_id,date(source.work_date)),personal={...ctx,self:true,resource:SELF};await requireRow(personal,{employment_id:e.id,person_id:e.person_id,company_id:e.company_id},'submit',['coworker_reference','start_at','end_at']);return{source,personal,authority:{employment_id:e.id,person_id:e.person_id,company_id:e.company_id}};}
